-- AutoERP portable legacy item-master import
-- Source: deziutge_pos (15).sql / products and owned relations
-- Target schema: laravel (7).sql
-- Import organization code: AUTOERP; currency: LKR
-- Stock quantities are deliberately excluded. Load opening stock through the Inventory module.
-- Generated: 2026-08-21

SET NAMES utf8mb4;
SET time_zone = '+00:00';

DROP TEMPORARY TABLE IF EXISTS `_legacy_item_categories`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_item_brands`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_items`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_item_units`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_item_prices`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_item_bundles`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_import_guard`;

CREATE TEMPORARY TABLE `_legacy_item_categories` (`code` varchar(50) NOT NULL PRIMARY KEY, `name` varchar(191) NOT NULL, `sort_order` int unsigned NOT NULL);
CREATE TEMPORARY TABLE `_legacy_item_brands` (`code` varchar(50) NOT NULL PRIMARY KEY, `name` varchar(191) NOT NULL);
CREATE TEMPORARY TABLE `_legacy_items` (
  `legacy_id` bigint unsigned NOT NULL PRIMARY KEY,
  `code` varchar(80) NOT NULL UNIQUE,
  `name` varchar(191) NOT NULL,
  `item_type` varchar(30) NOT NULL,
  `category_code` varchar(50) NOT NULL,
  `brand_code` varchar(50) NOT NULL,
  `uom_code` varchar(50) NOT NULL,
  `cost` decimal(20,6) NOT NULL,
  `price` decimal(20,6) NOT NULL,
  `is_stockable` tinyint(1) NOT NULL,
  `is_combo` tinyint(1) NOT NULL,
  `created_at` timestamp NULL,
  `updated_at` timestamp NULL,
  `metadata` longtext NOT NULL
);
CREATE TEMPORARY TABLE `_legacy_item_units` (`legacy_id` bigint unsigned NOT NULL, `uom_code` varchar(50) NOT NULL, `unit_role` varchar(30) NOT NULL, `is_default` tinyint(1) NOT NULL, PRIMARY KEY (`legacy_id`,`uom_code`,`unit_role`));
CREATE TEMPORARY TABLE `_legacy_item_prices` (`legacy_id` bigint unsigned NOT NULL, `price_type` varchar(30) NOT NULL, `uom_code` varchar(50) NOT NULL, `amount` decimal(20,6) NOT NULL, `effective_from` date NOT NULL, `recorded_from` datetime NOT NULL, `lineage_key` char(36) NOT NULL, PRIMARY KEY (`legacy_id`,`price_type`,`uom_code`));
CREATE TEMPORARY TABLE `_legacy_item_bundles` (`parent_legacy_id` bigint unsigned NOT NULL, `child_legacy_id` bigint unsigned NOT NULL, `quantity` decimal(20,6) NOT NULL, `line_type` varchar(30) NOT NULL, `unit_cost` decimal(20,6) NOT NULL, `sort_order` int unsigned NOT NULL, `uses_job_supervisor` tinyint(1) NOT NULL, PRIMARY KEY (`parent_legacy_id`,`child_legacy_id`,`sort_order`));
CREATE TEMPORARY TABLE `_legacy_import_guard` (`message` varchar(255) NOT NULL);
































START TRANSACTION;

SET @legacy_tenant_id := (SELECT `tenant_id` FROM `organization_units` WHERE `code` = 'AUTOERP' LIMIT 1);
SET @legacy_org_id := (SELECT `id` FROM `organization_units` WHERE `code` = 'AUTOERP' LIMIT 1);
SET @legacy_currency_id := (SELECT `id` FROM `currencies` WHERE `code` = 'LKR' LIMIT 1);

SELECT NULL WHERE (SELECT COUNT(*) FROM `organization_units` WHERE `code` = 'AUTOERP') <> 1;
SELECT NULL WHERE (SELECT COUNT(*) FROM `currencies` WHERE `code` = 'LKR') <> 1;
SELECT NULL WHERE EXISTS (
  SELECT 1 FROM `_legacy_items` s
  LEFT JOIN `unit_of_measures` u ON u.`tenant_id` = @legacy_tenant_id AND u.`code` = s.`uom_code` AND u.`deleted_at` IS NULL
  WHERE u.`id` IS NULL
);
SELECT NULL WHERE EXISTS (
  SELECT 1 FROM `_legacy_items` s
  JOIN `items` i ON i.`tenant_id` = @legacy_tenant_id AND (i.`sku` = s.`code` OR i.`barcode` = s.`code`)
  WHERE i.`code` <> s.`code`
);

SELECT @legacy_tenant_id,@legacy_org_id,NULL,s.`code`,s.`name`,'Legacy catalogue import category.',JSON_OBJECT('import_source','deziutge_pos (15).sql'),1,s.`sort_order`,UTC_TIMESTAMP(),UTC_TIMESTAMP(),NULL
FROM `_legacy_item_categories` s
WHERE NOT EXISTS (SELECT 1 FROM `item_categories` c WHERE c.`tenant_id`=@legacy_tenant_id AND c.`code`=s.`code`);

SELECT @legacy_tenant_id,@legacy_org_id,s.`code`,s.`name`,'Imported from the legacy product catalogue.',1,UTC_TIMESTAMP(),UTC_TIMESTAMP(),NULL
FROM `_legacy_item_brands` s
WHERE NOT EXISTS (SELECT 1 FROM `item_brands` b WHERE b.`tenant_id`=@legacy_tenant_id AND b.`code`=s.`code`);

SELECT @legacy_tenant_id,@legacy_org_id,c.`id`,b.`id`,s.`code`,s.`code`,s.`code`,s.`name`,NULL,s.`item_type`,'none',IF(s.`is_stockable`=1,'fifo','none'),u.`id`,NULL,NULL,NULL,s.`is_stockable`,s.`is_combo`,0,1,s.`metadata`,s.`created_at`,s.`updated_at`,NULL
FROM `_legacy_items` s
JOIN `item_categories` c ON c.`tenant_id`=@legacy_tenant_id AND c.`code`=s.`category_code`
JOIN `item_brands` b ON b.`tenant_id`=@legacy_tenant_id AND b.`code`=s.`brand_code`
JOIN `unit_of_measures` u ON u.`tenant_id`=@legacy_tenant_id AND u.`code`=s.`uom_code` AND u.`deleted_at` IS NULL
ON DUPLICATE KEY UPDATE
  `organization_unit_id`=VALUES(`organization_unit_id`),`item_category_id`=VALUES(`item_category_id`),`item_brand_id`=VALUES(`item_brand_id`),
  `sku`=VALUES(`sku`),`barcode`=VALUES(`barcode`),`name`=VALUES(`name`),`item_type`=VALUES(`item_type`),
  `tracking_type`=VALUES(`tracking_type`),`costing_method`=VALUES(`costing_method`),`base_uom_id`=VALUES(`base_uom_id`),
  `is_stockable`=VALUES(`is_stockable`),`is_combo`=VALUES(`is_combo`),`is_active`=1,`metadata`=VALUES(`metadata`),`updated_at`=VALUES(`updated_at`),`deleted_at`=NULL;

SELECT @legacy_tenant_id,@legacy_org_id,i.`id`,u.`id`,s.`unit_role`,1.000000,s.`is_default`,1,UTC_TIMESTAMP(),UTC_TIMESTAMP()
FROM `_legacy_item_units` s
JOIN `_legacy_items` si ON si.`legacy_id`=s.`legacy_id`
JOIN `items` i ON i.`tenant_id`=@legacy_tenant_id AND i.`code`=si.`code`
JOIN `unit_of_measures` u ON u.`tenant_id`=@legacy_tenant_id AND u.`code`=s.`uom_code` AND u.`deleted_at` IS NULL
ON DUPLICATE KEY UPDATE `organization_unit_id`=VALUES(`organization_unit_id`),`conversion_factor`=VALUES(`conversion_factor`),`is_default`=VALUES(`is_default`),`is_active`=1,`updated_at`=UTC_TIMESTAMP();

SELECT NULL FROM `_legacy_item_prices` s
JOIN `_legacy_items` si ON si.`legacy_id`=s.`legacy_id`
JOIN `items` i ON i.`tenant_id`=@legacy_tenant_id AND i.`code`=si.`code`
JOIN `unit_of_measures` u ON u.`tenant_id`=@legacy_tenant_id AND u.`code`=s.`uom_code`
JOIN `item_prices` p ON p.`tenant_id`=@legacy_tenant_id AND p.`item_id`=i.`id`
  AND p.`scope_key`=SHA2(CONCAT_WS('|',@legacy_org_id,'all_variants',s.`price_type`,@legacy_currency_id,u.`id`),256)
  AND p.`recorded_to` IS NULL
WHERE p.`amount`<>s.`amount`;

SELECT 1,@legacy_tenant_id,@legacy_org_id,i.`id`,NULL,s.`price_type`,@legacy_currency_id,u.`id`,s.`amount`,s.`effective_from`,NULL,
  SHA2(CONCAT_WS('|',@legacy_org_id,'all_variants',s.`price_type`,@legacy_currency_id,u.`id`),256),s.`lineage_key`,1,NULL,s.`recorded_from`,NULL,NULL,s.`recorded_from`,s.`recorded_from`
FROM `_legacy_item_prices` s
JOIN `_legacy_items` si ON si.`legacy_id`=s.`legacy_id`
JOIN `items` i ON i.`tenant_id`=@legacy_tenant_id AND i.`code`=si.`code`
JOIN `unit_of_measures` u ON u.`tenant_id`=@legacy_tenant_id AND u.`code`=s.`uom_code`
WHERE NOT EXISTS (
  SELECT 1 FROM `item_prices` p WHERE p.`tenant_id`=@legacy_tenant_id AND p.`item_id`=i.`id`
    AND p.`scope_key`=SHA2(CONCAT_WS('|',@legacy_org_id,'all_variants',s.`price_type`,@legacy_currency_id,u.`id`),256)
    AND p.`recorded_to` IS NULL
);

SELECT NULL FROM `item_bundles` b
JOIN `items` p ON p.`id`=b.`parent_item_id` AND p.`tenant_id`=@legacy_tenant_id
JOIN `_legacy_items` ps ON ps.`code`=p.`code` AND ps.`item_type`='combo'
WHERE NOT EXISTS (
  SELECT 1 FROM `_legacy_item_bundles` s
  JOIN `_legacy_items` cs ON cs.`legacy_id`=s.`child_legacy_id`
  JOIN `items` c ON c.`tenant_id`=@legacy_tenant_id AND c.`code`=cs.`code`
  WHERE s.`parent_legacy_id`=ps.`legacy_id` AND c.`id`=b.`child_item_id` AND s.`sort_order`=b.`sort_order`
    AND s.`quantity`=b.`quantity` AND s.`line_type`=b.`line_type` AND s.`unit_cost`=b.`unit_cost`
    AND s.`uses_job_supervisor`=b.`uses_job_supervisor`
);

SELECT @legacy_tenant_id,@legacy_org_id,p.`id`,c.`id`,NULL,s.`quantity`,u.`id`,s.`line_type`,s.`unit_cost`,s.`uses_job_supervisor`,1,s.`sort_order`,UTC_TIMESTAMP(),UTC_TIMESTAMP()
FROM `_legacy_item_bundles` s
JOIN `_legacy_items` ps ON ps.`legacy_id`=s.`parent_legacy_id`
JOIN `_legacy_items` cs ON cs.`legacy_id`=s.`child_legacy_id`
JOIN `items` p ON p.`tenant_id`=@legacy_tenant_id AND p.`code`=ps.`code`
JOIN `items` c ON c.`tenant_id`=@legacy_tenant_id AND c.`code`=cs.`code`
JOIN `unit_of_measures` u ON u.`tenant_id`=@legacy_tenant_id AND u.`code`=cs.`uom_code`
WHERE NOT EXISTS (
  SELECT 1 FROM `item_bundles` b WHERE b.`parent_item_id`=p.`id` AND b.`child_item_id`=c.`id` AND b.`sort_order`=s.`sort_order`
);

COMMIT;

SELECT 'legacy_items' AS `dataset`, COUNT(*) AS `imported_or_reconciled` FROM `items` i JOIN `_legacy_items` s ON s.`code`=i.`code` WHERE i.`tenant_id`=@legacy_tenant_id
UNION ALL SELECT 'legacy_item_units',COUNT(*) FROM `item_units` iu JOIN `items` i ON i.`id`=iu.`item_id` JOIN `_legacy_items` s ON s.`code`=i.`code` WHERE i.`tenant_id`=@legacy_tenant_id
UNION ALL SELECT 'legacy_current_prices',COUNT(*) FROM `item_prices` ip JOIN `items` i ON i.`id`=ip.`item_id` JOIN `_legacy_items` s ON s.`code`=i.`code` WHERE i.`tenant_id`=@legacy_tenant_id AND ip.`recorded_to` IS NULL
UNION ALL SELECT 'legacy_bundle_lines',COUNT(*) FROM `item_bundles` ib JOIN `items` i ON i.`id`=ib.`parent_item_id` JOIN `_legacy_items` s ON s.`code`=i.`code` WHERE i.`tenant_id`=@legacy_tenant_id;

DROP TEMPORARY TABLE IF EXISTS `_legacy_item_categories`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_item_brands`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_items`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_item_units`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_item_prices`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_item_bundles`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_import_guard`;
